"""Shared helpers for the Big Cat build tools (config, JSON I/O, geometry parsing)."""
from __future__ import annotations

import json
import math
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CONFIG_PATH = ROOT / "tools" / "coats_config.json"

GENERATED_NOTE = (
    "GENERATED by tools/build.py - do not edit by hand. Change tools/coats_config.json "
    "or tools/templates/ and rebuild."
)
GENERATED_KEY = "__generated__"


class BuildError(Exception):
    """A problem that should stop the build with a clear message."""


def rel(path: Path | str) -> str:
    """Path relative to the project root, for readable messages."""
    p = Path(path)
    try:
        return p.resolve().relative_to(ROOT).as_posix()
    except ValueError:
        return str(p)


# --------------------------------------------------------------------------- JSON

def load_json(path: Path | str):
    path = Path(path)
    if not path.is_file():
        raise BuildError(f"{rel(path)}: file not found")
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError as e:
        raise BuildError(f"{rel(path)}: invalid JSON: {e}") from None


def dumps(obj, indent: int = 2, inline_width: int = 100) -> str:
    """JSON with nested objects indented but short scalar lists kept on one line."""

    def fmt(o, level):
        pad = " " * (indent * level)
        pad2 = " " * (indent * (level + 1))
        if isinstance(o, dict):
            if not o:
                return "{}"
            items = [f"{pad2}{json.dumps(k)}: {fmt(v, level + 1)}" for k, v in o.items()]
            return "{\n" + ",\n".join(items) + "\n" + pad + "}"
        if isinstance(o, list):
            if not o:
                return "[]"
            if all(not isinstance(x, (dict, list)) for x in o):
                one = "[" + ", ".join(json.dumps(x) for x in o) + "]"
                if len(one) + len(pad) <= inline_width:
                    return one
            return "[\n" + ",\n".join(pad2 + fmt(x, level + 1) for x in o) + "\n" + pad + "]"
        return json.dumps(o)

    return fmt(obj, 0) + "\n"


def write_text(path: Path, text: str) -> None:
    """UTF-8 without BOM (a BOM breaks Bedrock), LF line endings."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")


def write_json(path: Path, obj) -> None:
    write_text(path, dumps(obj))


# ------------------------------------------------------------------------- config

@dataclass
class Paths:
    geometry: Path
    base_texture: Path
    tame_reference: Path
    protect_mask: Path
    coat_layers: Path
    bp: Path
    rp: Path
    bp_template: Path
    client_template: Path
    build: Path
    dist: Path
    coat_texture_dir: str  # pack-relative, e.g. "textures/entity/coats"

    @property
    def coat_dir_abs(self) -> Path:
        return self.rp / self.coat_texture_dir


def load_config() -> tuple[dict, Paths]:
    cfg = load_json(CONFIG_PATH)
    required = ["coat_count", "seed", "entity", "paths", "colors", "palettes", "pattern_weights"]
    missing = [k for k in required if k not in cfg]
    if missing:
        raise BuildError(f"{rel(CONFIG_PATH)}: missing keys {missing}")
    n = cfg["coat_count"]
    if not isinstance(n, int) or not 1 <= n <= 1000:
        raise BuildError(f"{rel(CONFIG_PATH)}: coat_count must be an int in 1..1000 (got {n!r})")
    p = cfg["paths"]
    paths = Paths(
        geometry=ROOT / p["geometry"],
        base_texture=ROOT / p["base_texture"],
        tame_reference=ROOT / p["tame_reference"],
        protect_mask=ROOT / p["protect_mask"],
        coat_layers=ROOT / p["coat_layers"],
        bp=ROOT / p["behavior_pack"],
        rp=ROOT / p["resource_pack"],
        bp_template=ROOT / p["behavior_template"],
        client_template=ROOT / p["client_entity_template"],
        build=ROOT / p["build_dir"],
        dist=ROOT / p["dist_dir"],
        coat_texture_dir=p["coat_texture_dir"].strip("/"),
    )
    return cfg, paths


def coat_name(i: int) -> str:
    return f"coat_{i:03d}"


def tame_name(i: int) -> str:
    return f"coat_{i:03d}_tame"


# ----------------------------------------------------------------------- geometry

Vec = tuple[float, float, float]


def _rot(v: Vec, deg: Vec, pivot: Vec) -> Vec:
    """Rotate v about pivot: X first, then Y, then Z (right-handed, degrees)."""
    x, y, z = (v[0] - pivot[0], v[1] - pivot[1], v[2] - pivot[2])
    ax, ay, az = (math.radians(a) for a in deg)
    if ax:
        c, s = math.cos(ax), math.sin(ax)
        y, z = y * c - z * s, y * s + z * c
    if ay:
        c, s = math.cos(ay), math.sin(ay)
        x, z = x * c + z * s, -x * s + z * c
    if az:
        c, s = math.cos(az), math.sin(az)
        x, y = x * c - y * s, x * s + y * c
    return (x + pivot[0], y + pivot[1], z + pivot[2])


def _rot_dir(n: Vec, deg: Vec) -> Vec:
    return _rot(n, deg, (0.0, 0.0, 0.0))


@dataclass
class Texel:
    """One texture pixel as it sits on the model surface."""
    px: int
    py: int
    bone: str
    cube: int
    face: str
    P: Vec  # surface point in model space (rest pose)
    N: Vec  # outward normal in model space
    w: dict = field(default_factory=dict)  # anatomy weights, filled in by build_coats

    @property
    def face_key(self) -> str:
        return f"{self.bone}/{self.cube}/{self.face}"


@dataclass
class Geometry:
    identifier: str
    width: int
    height: int
    bones: list[dict]
    texels: dict[tuple[int, int], Texel]  # unique texture pixel -> where it first appears
    surface: list[Texel]  # every face pixel of every cube (shared UVs appear twice)
    cube_bounds: dict[tuple[str, int], tuple[Vec, Vec]]


def load_geometry(path: Path, identifier: str, rest_rotations: dict | None = None) -> Geometry:
    """Parse a Bedrock geometry file and map every UV pixel to a point on the model.

    Box-UV layout (u, v = cube uv; w, h, d = cube size x, y, z):
        up    (u+d,     v)    w x d      down  (u+d+w,   v)    w x d
        west  (u,       v+d)  d x h      north (u+d,     v+d)  w x h
        east  (u+d+w,   v+d)  d x h      south (u+2d+w,  v+d)  w x h
    north is -z (the cat's front). Left/right may be mirrored relative to the game,
    which does not matter for a symmetric cat.

    rest_rotations: {bone: {"rotation": [x,y,z], "pivot": [x,y,z]}} applied to that
    bone's own cubes only (the vanilla cat body is drawn upright in the file and
    turned horizontal by the engine).
    """
    data = load_json(path)
    geos = data.get("minecraft:geometry")
    if not isinstance(geos, list):
        raise BuildError(f"{rel(path)}: no 'minecraft:geometry' list (old-format geometry is not supported)")
    geo = next((g for g in geos if g.get("description", {}).get("identifier") == identifier), None)
    if geo is None:
        raise BuildError(f"{rel(path)}: geometry '{identifier}' not found")
    desc = geo["description"]
    width, height = int(desc["texture_width"]), int(desc["texture_height"])
    bones = geo.get("bones", [])
    by_name = {b["name"]: b for b in bones}
    rest_rotations = rest_rotations or {}

    def to_model(bone_name: str, p: Vec, n: Vec, own: bool = True) -> tuple[Vec, Vec]:
        bone = by_name[bone_name]
        if own and bone_name in rest_rotations:
            rr = rest_rotations[bone_name]
            p = _rot(p, tuple(rr["rotation"]), tuple(rr.get("pivot", bone.get("pivot", [0, 0, 0]))))
            n = _rot_dir(n, tuple(rr["rotation"]))
            off = rr.get("offset", (0, 0, 0))
            p = (p[0] + off[0], p[1] + off[1], p[2] + off[2])
        if bone.get("rotation"):
            p = _rot(p, tuple(bone["rotation"]), tuple(bone.get("pivot", [0, 0, 0])))
            n = _rot_dir(n, tuple(bone["rotation"]))
        if bone.get("parent"):
            return to_model(bone["parent"], p, n, own=False)
        return p, n

    texels: dict[tuple[int, int], Texel] = {}
    surface: list[Texel] = []
    cube_bounds: dict[tuple[str, int], tuple[Vec, Vec]] = {}
    owner: dict[tuple[int, int], tuple] = {}

    for bone in bones:
        for ci, cube in enumerate(bone.get("cubes", [])):
            if cube.get("mirror") or bone.get("mirror"):
                raise BuildError(f"{rel(path)}: bone '{bone['name']}' uses mirror, which build_coats does not support")
            uv = cube.get("uv")
            if not (isinstance(uv, list) and len(uv) == 2):
                raise BuildError(f"{rel(path)}: bone '{bone['name']}' cube {ci}: only box UV is supported")
            x0, y0, z0 = (float(c) for c in cube["origin"])
            sw, sh, sd = (float(c) for c in cube["size"])
            w, h, d = (int(round(c)) for c in (sw, sh, sd))
            u, v = int(uv[0]), int(uv[1])
            # face: (rect x, rect y, rect w, rect h, point(s, t) for s,t in [0,1], normal)
            faces = {
                "up":    (u + d, v, w, d, lambda s, t: (x0 + s * sw, y0 + sh, z0 + sd - t * sd), (0, 1, 0)),
                "down":  (u + d + w, v, w, d, lambda s, t: (x0 + s * sw, y0, z0 + t * sd), (0, -1, 0)),
                "west":  (u, v + d, d, h, lambda s, t: (x0, y0 + sh - t * sh, z0 + sd - s * sd), (-1, 0, 0)),
                "north": (u + d, v + d, w, h, lambda s, t: (x0 + s * sw, y0 + sh - t * sh, z0), (0, 0, -1)),
                "east":  (u + d + w, v + d, d, h, lambda s, t: (x0 + sw, y0 + sh - t * sh, z0 + s * sd), (1, 0, 0)),
                "south": (u + 2 * d + w, v + d, w, h, lambda s, t: (x0 + sw - s * sw, y0 + sh - t * sh, z0 + sd), (0, 0, 1)),
            }
            corners = [to_model(bone["name"], (x0 + a * sw, y0 + b * sh, z0 + c * sd), (0, 0, 1))[0]
                       for a in (0, 1) for b in (0, 1) for c in (0, 1)]
            cube_bounds[(bone["name"], ci)] = (
                tuple(min(c[i] for c in corners) for i in range(3)),
                tuple(max(c[i] for c in corners) for i in range(3)),
            )
            for fname, (rx, ry, rw, rh, point, normal) in faces.items():
                for ty in range(rh):
                    for tx in range(rw):
                        px, py = rx + tx, ry + ty
                        if not (0 <= px < width and 0 <= py < height):
                            raise BuildError(
                                f"{rel(path)}: bone '{bone['name']}' cube {ci} face {fname} "
                                f"leaves the {width}x{height} texture at pixel ({px},{py})")
                        P, N = to_model(bone["name"], point((tx + 0.5) / rw, (ty + 0.5) / rh), normal)
                        t = Texel(px, py, bone["name"], ci, fname, P, N)
                        surface.append(t)
                        key = (px, py)
                        sig = (u, v, w, h, d, fname)  # identical cubes (e.g. left/right legs) share UVs
                        if key not in texels:
                            texels[key] = t
                            owner[key] = sig
                        elif owner[key] != sig:
                            print(f"  warning: UV overlap at pixel {key}: {texels[key].face_key} and {t.face_key}")
    return Geometry(identifier, width, height, bones, texels, surface, cube_bounds)
